{
  "assessment": "The source provides a complete quantitative cluster for the incompressible kinetic energy scaling with quench duration at two temperatures (T=10^-6 and T=1), including fitted power laws, statistical provenance, and fixed simulation conditions. The selected cluster is supported by the main text, End Matter, and reviewer figure evidence. The source reports two temperature branches with distinct fits and realizations counts; these are encoded as separate claims with branch-specific fixed conditions. The quench duration control is supported as a continuous interval [100,1000] for the fitted curves, based on the reviewer evidence and the source's stated range for the vortex scaling. The case is authoring-ready.",
  "case_authoring_ready": true,
  "source": {
    "citation": "Seong-Ho Shinn, Spontaneous Quantum Turbulence in a Newborn Bose-Einstein Condensate via the Kibble-Zurek Mechanism, Physical Review Letters (2026), DOI:10.1103/b16v-hwp2",
    "journal_doi": "10.1103/b16v-hwp2",
    "arxiv_versioned_id": "2506.21670v3"
  },
  "paper_scope": "The paper proposes and numerically simulates spontaneous quantum turbulence (SQT) in a 2D Bose-Einstein condensate formed via a thermal quench, using the stochastic projected Gross-Pitaevskii equation. It establishes Kibble-Zurek scaling of vortex number and equilibration time, Kolmogorov scaling of the incompressible kinetic energy spectrum, and universal collapse of the incompressible kinetic energy with quench duration at two temperatures.",
  "mechanisms": [
    {
      "mechanism_id": "kzm_incompressible_energy_scaling",
      "statement": "The incompressible kinetic energy at equilibration scales with quench duration as E_i proportional to tau_Q^{-(1+2 nu)/(1+z nu)}, derived from the sum of vortex contributions with density and correlation length scaling according to the Kibble-Zurek mechanism.",
      "equations": [
        "E_i \\\\propto \\\\tau_Q^{-(1+2\\\\nu)/(1+z\\\\nu)}",
        "E_i \\\\simeq (1/2) n_v \\\\int_{D_{\\\\hat{\\\\xi}}} |u_v(r)|^2 d^2r",
        "\\\\int_{D_{\\\\hat{\\\\xi}}} |u_v(r)|^2 d^2r \\\\simeq 2\\\\pi \\\\rho \\\\ln(\\\\hat{\\\\xi}/r_v)"
      ],
      "variable_names": [
        "E_i",
        "tau_Q",
        "nu",
        "z",
        "n_v",
        "rho",
        "hat_xi",
        "r_v"
      ],
      "parameters": [
        {
          "name": "nu_critical_exponent",
          "value": 0.5,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "correlation-length critical exponent (mean-field value)",
          "anchors": [
            {
              "line_start": 167,
              "line_end": 167,
              "support": "Using the mean-field values of the critical exponents nu = 1/2 and z = 2"
            }
          ]
        },
        {
