          "value": 2,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "dynamic critical exponent (mean-field value)",
          "anchors": [
            {
              "line_start": 167,
              "line_end": 167,
              "support": "Using the mean-field values of the critical exponents nu = 1/2 and z = 2"
            }
          ]
        },
        {
          "name": "Ei_amplitude_T1e6",
